// the life zones its range covers
function zoneOf(dmin, dmax) {
  const z = [];
  if (dmin < 200) z.push('Sunlight');
  if (dmin < 1000 && dmax >= 200) z.push('Twilight');
  if (dmin < 4000 && dmax >= 1000) z.push('Midnight');
  if (dmax >= 4000) z.push('Abyss');
  return z.join(', ');
}
export const MORE_SPECIES = L.map(([name, sci, cat, dmin, dmax, oceans, size, desc, v, x], i) =>
  ({ id: 189 + i, name, sci, cat, dmin, dmax, zone: zoneOf(dmin, dmax), oceans, size, desc, v, x: x || {} }));
